(async () => {
  const { accessSync, constants } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('INPUT_PATH env var is required');
  if (!outputPath) throw new Error('OUTPUT_PATH env var is required');
  try { accessSync(inputPath, constants.R_OK); } catch { throw new Error('Input file not readable: ' + inputPath); }
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { Yaml2json } = await import('@adius/yaml2json');
  const { createReadStream } = await import('node:fs');
  const { pipeline } = await import('node:stream/promises');
  const { Transform } = await import('node:stream');
  const { writeFile } = await import('node:fs').then(m => m.promises);
  let output = '';
  const collector = new Transform({
    writableObjectMode: true,
    transform(chunk, _enc, cb) {
      output += JSON.stringify(chunk) + '\n';
      cb();
    }
  });
  await pipeline(
    createReadStream(globalThis.inputPath),
    new Yaml2json(),
    collector
  );
  await writeFile(globalThis.outputPath, output);
  globalThis.resultPath = globalThis.outputPath;
})();
